{
  "$comment": "Read-only LXC observability tools. Zero mutation risk; ship first.",
  "tools": [
    {
      "name": "get_lxc_container",
      "description": "Full detail for one LXC/Incus guest: status, all IPv4/IPv6 addresses with lease type (dhcp/static) and remaining lease time, security config (privileged, nesting, keyctl), resource limits, boot.autostart, registered startup script path and working dir, and snapshot list. This is the LXC counterpart of get_project.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string", "description": "Container name from list_lxc_containers (without the pp- prefix)." }
        },
        "required": ["container"]
      }
    },
    {
      "name": "list_lxc_files",
      "description": "List files under a directory inside an LXC guest (name, size, mode, mtime, symlink target). Counterpart of list_project_files. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "path": { "type": "string", "description": "Absolute directory inside the guest, e.g. /opt/app." },
          "recursive": { "type": "boolean", "description": "Recurse into subdirectories (default false). Capped at 2000 entries." }
        },
        "required": ["container", "path"]
      }
    },
    {
      "name": "search_lxc_files",
      "description": "Grep text files under a directory inside an LXC guest. Counterpart of search_project_files. Returns matching path, line number, and line (capped at 200 matches). Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "path": { "type": "string", "description": "Absolute directory to search under." },
          "pattern": { "type": "string", "description": "Regular expression to search for." },
          "glob": { "type": "string", "description": "Optional filename glob filter, e.g. *.yml." }
        },
        "required": ["container", "path", "pattern"]
      }
    },
    {
      "name": "get_lxc_logs",
      "description": "Fetch recent log output from inside an LXC guest without redeploying anything: journald for a named unit, the registered startup service, or docker compose logs for a compose project directory. Returns the last N lines (default 100, max 1000). Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "source": {
            "type": "string",
            "enum": ["startup", "journal", "docker-compose"],
            "description": "startup = the registered ProxyPilot startup service; journal = a systemd unit (requires unit); docker-compose = compose logs (requires compose_dir)."
          },
          "unit": { "type": "string", "description": "systemd unit name when source=journal, e.g. docker.service." },
          "compose_dir": { "type": "string", "description": "Directory containing docker-compose.yml when source=docker-compose." },
          "lines": { "type": "number", "description": "Line count, default 100, max 1000." }
        },
        "required": ["container", "source"]
      }
    },
    {
      "name": "probe_lxc_port",
      "description": "From inside an LXC guest, probe a host:port and report reachability. TCP connect result, and for http/https the status code, response time, server header, and whether a WebSocket upgrade handshake completes. Never returns a response body. This is the one-call answer to 'is the app up behind the proxy' — in the field this distinction (edge 502 vs in-guest 401) required rewriting the boot script.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "host": { "type": "string", "description": "Target host, default 127.0.0.1." },
          "port": { "type": "number" },
          "scheme": { "type": "string", "enum": ["tcp", "http", "https"], "description": "Default http." },
          "path": { "type": "string", "description": "URL path for http/https probes, default /." },
          "test_websocket": { "type": "boolean", "description": "Also attempt a WebSocket upgrade on the same path (default false)." },
          "timeout_seconds": { "type": "number", "description": "Default 10, max 60." }
        },
        "required": ["container", "port"]
      }
    },
    {
      "name": "get_lxc_startup",
      "description": "Return the registered startup script for an LXC guest: script path, working dir, full script content, last run time, and last exit code. Today this is only visible as a side effect of inspect_lxc_zip. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" }
        },
        "required": ["container"]
      }
    }
  ]
}

{
  "$comment": "Constrained execution inside LXC guests. Mirrors run_project_command semantics exactly: argv whitespace-split, no shell, allowlist-enforced, output-capped.",
  "tools": [
    {
      "name": "run_lxc_command",
      "description": "Run one allowlisted command inside an LXC guest. Same contract as run_project_command: the command is split on whitespace and executed directly (no shell — pipes, redirects, ;, && and $() are rejected), output truncated to the last 64 KB of stdout/stderr, returns exit_code and timed_out. The allowlist (policy/lxc-command-allowlist.json) is read-biased: docker/compose status and logs, systemctl status, ip, ss, sysctl -n, journalctl, curl, df, free, plus docker compose up/restart/pull for the registered app dir. This single tool eliminates the edit-boot-script-and-redeploy debugging loop.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "command": { "type": "string", "description": "e.g. \"docker compose ps -a\" or \"ss -ltnp\". Validated against the allowlist before execution." },
          "working_dir": { "type": "string", "description": "Absolute directory to run in; default the registered startup working dir." },
          "timeout_seconds": { "type": "number", "description": "Kill after this many seconds. Default 120, max 1800." }
        },
        "required": ["container", "command"]
      }
    },
    {
      "name": "rerun_startup_v2",
      "description": "Superset of rerun_startup: re-run the registered startup script with a timeout and a dry-run mode. dry_run=true returns the script content and working dir that WOULD run, without executing. Output truncated to the last 64 KB; result includes exit_code and timed_out, matching run_project_command.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "timeout_seconds": { "type": "number", "description": "Default 600, max 1800." },
          "dry_run": { "type": "boolean", "description": "Report what would run without running it (default false)." }
        },
        "required": ["container"]
      }
    }
  ]
}

{
  "$comment": "LXC lifecycle and configuration. Every mutating tool requires confirm:true and snapshots first. Deliberately NO delete verb.",
  "tools": [
    {
      "name": "create_lxc_container",
      "description": "Create a new LXC/Incus guest and register it with ProxyPilot so it appears in list_lxc_containers. Creation-only, so inherently non-destructive: fails if the name already exists, never replaces. Sets the Docker-readiness flags correctly at birth (security.nesting=true, keyctl where the host supports it) so the keyring/nesting failures seen in the field cannot occur on new guests.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string", "description": "Guest name (ProxyPilot adds its pp- prefix). Fails if taken." },
          "image": { "type": "string", "description": "OS image alias, e.g. debian/12. Default debian/12." },
          "cpu": { "type": "number", "description": "vCPU limit, default 2." },
          "memory_gb": { "type": "number", "description": "RAM limit in GB, default 4." },
          "disk_gb": { "type": "number", "description": "Root disk in GB, default 20." },
          "docker_ready": { "type": "boolean", "description": "Set security.nesting (and keyctl on Proxmox-style hosts) for running Docker inside. Default true." },
          "autostart": { "type": "boolean", "description": "boot.autostart, default true." },
          "confirm": { "type": "boolean", "description": "Must be true. Present for uniformity with all mutating tools." }
        },
        "required": ["name", "confirm"]
      }
    },
    {
      "name": "control_lxc_container",
      "description": "Start, stop (clean shutdown), or restart an LXC guest. No force-kill and no delete. In the field, applying a privilege change required a host-side 'incus restart' no MCP tool could perform. Requires confirm:true.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "action": { "type": "string", "enum": ["start", "stop", "restart"] },
          "confirm": { "type": "boolean", "description": "Must be true." }
        },
        "required": ["container", "action", "confirm"]
      }
    },
    {
      "name": "set_lxc_config",
      "description": "Set one allowlisted Incus config key on a guest (see policy/lxc-config-allowlist.json): security.nesting, security.privileged, limits.cpu, limits.memory, boot.autostart. Anything outside the allowlist is rejected. security.privileged=true additionally requires acknowledge_risk:true and returns a warning that container root becomes host root. Takes an automatic snapshot before applying. Reports whether a restart is needed for the key to take effect.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "key": { "type": "string", "enum": ["security.nesting", "security.privileged", "limits.cpu", "limits.memory", "boot.autostart"] },
          "value": { "type": "string", "description": "New value, e.g. \"true\", \"4\", \"8GB\"." },
          "confirm": { "type": "boolean", "description": "Must be true." },
          "acknowledge_risk": { "type": "boolean", "description": "Required (true) only when setting security.privileged=true." }
        },
        "required": ["container", "key", "value", "confirm"]
      }
    },
    {
      "name": "snapshot_lxc_container",
      "description": "Take a named snapshot of a guest. Additive by definition — this is the safety primitive that makes every other mutating tool in this spec safe to expose. Also lists existing snapshots when called with list:true. No restore/delete verb over MCP; restoring is a deliberate host-side act.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "name": { "type": "string", "description": "Snapshot name; default an ISO-8601 timestamp." },
          "list": { "type": "boolean", "description": "If true, just return existing snapshots and take none." }
        },
        "required": ["container"]
      }
    },
    {
      "name": "set_lxc_network",
      "description": "Pin a guest's addressing: convert the current DHCP lease to a static reservation (recommended default) or assign a specific static IP on the guest's bridge. In the field, the working deployment sat on a dynamic lease whose next renewal would silently reproduce the edge 502 that had just been debugged. Warns if any route (see routing tools) currently targets an IP this change would abandon. Requires confirm:true; snapshots first.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "mode": { "type": "string", "enum": ["reserve-current", "static"], "description": "reserve-current = DHCP reservation for the address the guest holds now; static = assign the address given in ip." },
          "ip": { "type": "string", "description": "IPv4 address, required when mode=static." },
          "confirm": { "type": "boolean", "description": "Must be true." }
        },
        "required": ["container", "mode", "confirm"]
      }
    },
    {
      "name": "lxc_file_diff",
      "description": "Diff a file inside a guest against its .old backup (written by write_lxc_file / apply_lxc_zip), or between two arbitrary text file paths in the same guest. Counterpart of project_git_diff for the unversioned LXC world. Read-only; pairs with restore_lxc_file.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "path": { "type": "string", "description": "File to diff; compared against <path>.old unless against is set." },
          "against": { "type": "string", "description": "Optional second path to diff against instead of the .old backup." }
        },
        "required": ["container", "path"]
      }
    },
    {
      "name": "restore_lxc_file",
      "description": "Restore a file from its .old backup, swapping the current version into .old (so restore is itself reversible). Completes the backup story write_lxc_file starts: today .old files are written but nothing can restore them. Requires confirm:true.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "container": { "type": "string" },
          "path": { "type": "string", "description": "The live file path; its .old must exist." },
          "confirm": { "type": "boolean", "description": "Must be true." }
        },
        "required": ["container", "path", "confirm"]
      }
    }
  ]
}

{
  "$comment": "Edge routing / reverse-proxy tools. This is the layer where the field session's actual failure lived, and it was completely invisible over MCP.",
  "tools": [
    {
      "name": "list_routes",
      "description": "List every hostname the edge proxy serves: domain, upstream target (ip:port or static-site id or project id), TLS cert state, websocket-upgrade flag, enabled/disabled. Surfaces orphaned routes (upstream unreachable or unregistered) and duplicate hostnames. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {}
      }
    },
    {
      "name": "get_route",
      "description": "Full detail for one hostname: upstream target and how it is resolved, TLS cert issuer/expiry, websocket-upgrade and forwarded-header config, and recent error counts (e.g. 502s in the last hour). In the field, a 502 caused by a stale upstream IP was diagnosable only by inference from an external fetch failure. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "domain": { "type": "string", "description": "Fully qualified hostname, e.g. web.fractionate.ai." }
        },
        "required": ["domain"]
      }
    },
    {
      "name": "test_route",
      "description": "Probe a route from the edge proxy's own vantage point: DNS resolution, upstream TCP connect, HTTP status through the full proxy path, response time, and — when websocket=true is configured or requested — whether a WebSocket upgrade handshake completes end-to-end. Distinguishes in one call the three failure classes that look identical from outside: DNS, proxy-to-upstream, and app-level. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "domain": { "type": "string" },
          "path": { "type": "string", "description": "URL path to probe, default /." },
          "test_websocket": { "type": "boolean", "description": "Attempt a WS upgrade through the proxy (default: whatever the route has configured)." }
        },
        "required": ["domain"]
      }
    },
    {
      "name": "set_route",
      "description": "Create or update the binding for one hostname: upstream ip:port (or container name + port, resolved and kept in sync with set_lxc_network reservations), websocket upgrade on/off, and TLS issuance. Updating an existing route requires confirm_overwrite:true and returns the previous binding in the result so the change is reversible by a second call. No delete verb — disable instead.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "domain": { "type": "string" },
          "upstream_container": { "type": "string", "description": "LXC guest name; mutually exclusive with upstream_ip. Preferred: survives IP changes." },
          "upstream_ip": { "type": "string", "description": "Literal upstream IPv4; mutually exclusive with upstream_container." },
          "upstream_port": { "type": "number" },
          "websocket": { "type": "boolean", "description": "Pass Upgrade/Connection headers. Default true — modern remote-desktop and dev-server upstreams break without it, and the failure mode (page loads, then black screen) is misleading." },
          "tls": { "type": "boolean", "description": "Issue/renew a certificate for the domain. Default true." },
          "enabled": { "type": "boolean", "description": "Set false to park a route without deleting it." },
          "confirm_overwrite": { "type": "boolean", "description": "Required (true) when the domain already has a binding." }
        },
        "required": ["domain", "upstream_port"]
      }
    }
  ]
}

{
  "$comment": "Static-site tools, brought to parity with the projects surface. Prerequisite: the list_static_sites 'no such column: domain' bug is fixed (docs/01-bugfixes.md #2).",
  "tools": [
    {
      "name": "create_static_site",
      "description": "Register a new static site: name, domain, and an empty (or placeholder) docroot, with TLS issuance. Creation-only; fails if the domain is already routed. Returns the site id used by the zip deploy tools and the file tools below.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "domain": { "type": "string" },
          "tls": { "type": "boolean", "description": "Default true." },
          "confirm": { "type": "boolean", "description": "Must be true." }
        },
        "required": ["name", "domain", "confirm"]
      }
    },
    {
      "name": "get_static_site",
      "description": "Detail for one static site: domain, docroot size and file count, last deploy time, TLS cert issuer and expiry, and route health (edge probe status). Counterpart of get_project. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "site_id": { "type": "number" }
        },
        "required": ["site_id"]
      }
    },
    {
      "name": "list_static_site_files",
      "description": "List the deployed files of a static site (path, size, mtime). Today the only view into a deployed site is nothing at all — the zip apply is write-only. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "site_id": { "type": "number" },
          "subdir": { "type": "string", "description": "Limit listing to a subdirectory of the docroot." }
        },
        "required": ["site_id"]
      }
    },
    {
      "name": "read_static_site_file",
      "description": "Read one text file from a static site's docroot (up to 512 KB, refuses binary) — same contract as read_lxc_file. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "site_id": { "type": "number" },
          "path": { "type": "string", "description": "Path relative to the docroot." }
        },
        "required": ["site_id", "path"]
      }
    },
    {
      "name": "write_static_site_file",
      "description": "Write one text file into a static site's docroot, with the write_lxc_file safety contract: existing files require confirm_overwrite:true and the previous version is kept as <path>.old. Enables single-file fixes (a typo, a robots.txt, one stylesheet) without a full zip redeploy.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "site_id": { "type": "number" },
          "path": { "type": "string", "description": "Path relative to the docroot." },
          "content": { "type": "string" },
          "confirm_overwrite": { "type": "boolean", "description": "Required (true) when the file exists." }
        },
        "required": ["site_id", "path", "content"]
      }
    },
    {
      "name": "get_static_site_cert",
      "description": "TLS certificate status for a site's domain: issuer, not-before/not-after, days remaining, last renewal attempt and its outcome. Read-only.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "site_id": { "type": "number" }
        },
        "required": ["site_id"]
      }
    }
  ]
}

{
  "$comment": "Writable Incus config keys for set_lxc_config. Any key not listed is rejected. Every write snapshots the guest first.",
  "keys": {
    "security.nesting": {
      "values": ["true", "false"],
      "restart_required": true,
      "gate": "confirm",
      "note": "Required true for Docker inside the guest. Low risk."
    },
    "security.privileged": {
      "values": ["true", "false"],
      "restart_required": true,
      "gate": "confirm + acknowledge_risk when setting true",
      "warning": "Privileged means container root IS host root: a compromise inside the guest is a host compromise. Prefer raising kernel.keys.* sysctls on the host, which fixes the Docker keyring failure with isolation intact. Also changes uid mapping — file ownership inside the guest shifts, so existing data directories may need re-chowning.",
      "note": "This exact flip was the field session's blocker; the tool must present the warning, not just apply the change."
    },
    "limits.cpu": {
      "values": "positive integer as string",
      "restart_required": false,
      "gate": "confirm"
    },
    "limits.memory": {
      "values": "size string, e.g. 4GB",
      "restart_required": false,
      "gate": "confirm",
      "note": "Browser workloads need >= 4GB; Chrome OOMs at 2GB."
    },
    "boot.autostart": {
      "values": ["true", "false"],
      "restart_required": false,
      "gate": "confirm"
    }
  },
  "explicitly_not_writable": {
    "raw.lxc": "Arbitrary LXC config injection — equivalent to unrestricted host-level control.",
    "raw.idmap": "uid-mapping changes can orphan every file in the guest.",
    "security.syscalls.*": "Syscall filter changes are host-security-relevant and rare enough to stay manual.",
    "devices (disk/nic passthrough)": "Device attachment reaches host resources; keep manual."
  }
}
